CREATE TABLE IF NOT EXISTS page_views (id TEXT PRIMARY KEY, at INTEGER NOT NULL, day TEXT NOT NULL, reader TEXT NOT NULL, visit TEXT NOT NULL, visit_first INTEGER NOT NULL DEFAULT 0, reader_new INTEGER NOT NULL DEFAULT 0, publisher TEXT, title TEXT, title_admin TEXT, kind TEXT, path TEXT, issue_id TEXT, issue_code TEXT, ref_kind TEXT, ref_host TEXT, utm_source TEXT, utm_medium TEXT, utm_content TEXT, device TEXT, engaged_ms INTEGER NOT NULL DEFAULT 0, last_at INTEGER, script TEXT);
CREATE INDEX IF NOT EXISTS pv_title_day ON page_views (title, day);
CREATE INDEX IF NOT EXISTS pv_reader ON page_views (reader, at);
CREATE INDEX IF NOT EXISTS pv_visit ON page_views (visit);
CREATE INDEX IF NOT EXISTS pv_issue ON page_views (issue_code);
CREATE TABLE IF NOT EXISTS ad_views (id TEXT PRIMARY KEY, page_view_id TEXT NOT NULL, at INTEGER NOT NULL, day TEXT NOT NULL, reader TEXT, visit TEXT, publisher TEXT, title TEXT, kind TEXT, issue_id TEXT, issue_code TEXT, ad_id TEXT, advertiser_id TEXT, slot TEXT, shape TEXT, href_host TEXT, max_ms INTEGER NOT NULL DEFAULT 0, total_ms INTEGER NOT NULL DEFAULT 0, ratio REAL, seen_ms INTEGER, seen INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS av_ad_day ON ad_views (ad_id, day);
CREATE INDEX IF NOT EXISTS av_adv_day ON ad_views (advertiser_id, day);
CREATE INDEX IF NOT EXISTS av_title_day ON ad_views (title, day);
CREATE INDEX IF NOT EXISTS av_pv ON ad_views (page_view_id);
CREATE TABLE IF NOT EXISTS clicks (id TEXT PRIMARY KEY, at INTEGER NOT NULL, day TEXT NOT NULL, source TEXT NOT NULL, page_view_id TEXT, reader TEXT, visit TEXT, publisher TEXT, title TEXT, kind TEXT, issue_id TEXT, issue_code TEXT, ad_id TEXT, advertiser_id TEXT, slot TEXT, shape TEXT, link_type TEXT, dest TEXT, dest_host TEXT, internal INTEGER NOT NULL DEFAULT 0, label TEXT, link_code TEXT, scanner INTEGER NOT NULL DEFAULT 0);
CREATE INDEX IF NOT EXISTS ck_title_day ON clicks (title, day);
CREATE INDEX IF NOT EXISTS ck_adv_day ON clicks (advertiser_id, day);
CREATE INDEX IF NOT EXISTS ck_issue ON clicks (issue_code);
CREATE TABLE IF NOT EXISTS email_opens (id TEXT PRIMARY KEY, at INTEGER NOT NULL, day TEXT NOT NULL, issue_id TEXT, issue_code TEXT, publisher TEXT, title TEXT, list TEXT, recipient TEXT, apple INTEGER NOT NULL DEFAULT 0, first_open INTEGER NOT NULL DEFAULT 0, ua_class TEXT);
CREATE INDEX IF NOT EXISTS eo_issue ON email_opens (issue_code, list);
CREATE TABLE IF NOT EXISTS sends (issue_id TEXT NOT NULL, provider TEXT NOT NULL, campaign TEXT NOT NULL DEFAULT '', issue_code TEXT, publisher TEXT, title TEXT, sent_at INTEGER, ordered INTEGER, delivered INTEGER, opens_unique INTEGER, opens_total INTEGER, clicks_unique INTEGER, clicks_total INTEGER, bounces INTEGER, unsubscribes INTEGER, measured_at INTEGER, fetched_at INTEGER, raw TEXT, PRIMARY KEY (issue_id, provider, campaign));
CREATE TABLE IF NOT EXISTS provider_clicks (issue_id TEXT NOT NULL, provider TEXT NOT NULL, campaign TEXT NOT NULL DEFAULT '', url TEXT NOT NULL, clicks_total INTEGER, clicks_unique INTEGER, issue_code TEXT, publisher TEXT, title TEXT, advertiser_id TEXT, ad_id TEXT, slot TEXT, link_type TEXT, dest_host TEXT, measured_at INTEGER, fetched_at INTEGER, PRIMARY KEY (issue_id, provider, campaign, url));
CREATE INDEX IF NOT EXISTS pc_adv ON provider_clicks (advertiser_id);
CREATE INDEX IF NOT EXISTS pc_issue ON provider_clicks (issue_code, provider);
CREATE TABLE IF NOT EXISTS links (code TEXT PRIMARY KEY, dest TEXT NOT NULL, issue_id TEXT, issue_code TEXT, publisher TEXT, title TEXT, advertiser_id TEXT, ad_id TEXT, slot TEXT, link_type TEXT, created_at INTEGER);
CREATE TABLE IF NOT EXISTS ga4_daily (title TEXT NOT NULL, day TEXT NOT NULL, metric TEXT NOT NULL, value REAL, fetched_at INTEGER, PRIMARY KEY (title, day, metric));
CREATE TABLE IF NOT EXISTS source_status (source TEXT PRIMARY KEY, last_ok_at INTEGER, last_error_at INTEGER, last_error TEXT, last_count INTEGER, note TEXT);
CREATE INDEX IF NOT EXISTS pv_day ON page_views (day);
CREATE INDEX IF NOT EXISTS av_day ON ad_views (day);
CREATE INDEX IF NOT EXISTS ck_day ON clicks (day);
